<script setup lang="ts">
import {renderMarkdown} from '@/shared/markdown'
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {frontierApi,type FrontierConfig,type FrontierTopic,type FrontierRun,type FrontierItem} from '@/api/frontier'
import {schedulesApi} from '@/api/schedules'
import {papersApi} from '@/api/papers'
import {uid32} from '@/api/client'
import type {Collection} from '@/api/types'
import StateFeedback from '@/components/StateFeedback.vue'
const emit=defineEmits<{'open-paper':[id:number];'open-session':[id:number];'library-updated':[]}>()
const topics=ref<FrontierTopic[]>([]),selected=ref<number|null>(null),tab=ref<'reports'|'discoveries'|'runs'>('reports')
const reports=ref<FrontierRun[]>([]),runs=ref<FrontierRun[]>([]),items=ref<FrontierItem[]>([]),cursor=ref<number|null>(null)
const collections=ref<Collection[]>([]),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),newReports=ref(false)
const itemCursor=ref<string|null>(null)
const topic=computed(()=>topics.value.find(t=>t.id===selected.value)),pendingOnly=ref(false)
const domainFilter=ref('')
const domains=computed(()=>[...new Set(topics.value.flatMap(t=>t.config.domains))])
const navTopics=computed(()=>topics.value.filter(t=>!domainFilter.value||t.config.domains.includes(domainFilter.value)))
const expanded=ref<Set<string>>(new Set()),marked=ref<Set<string>>(new Set())
const formOpen=ref(false),editId=ref<number|null>(null),editRevision=ref(1),title=ref(''),config=ref<FrontierConfig>(defaults())
const fields=ref({domains:'',keywords:'',authors:'',teams:'',exclude:''}),newCategory=ref('')
const decisionItem=ref<FrontierItem|null>(null),decisionCategories=ref<number[]>([]),confirmDistinct=ref(false)
const labels:Record<string,string>={queued:'排队中',running:'执行中',dispatching:'提交中',succeeded:'已完成',partial:'部分完成',failed:'失败',cancelled:'已取消',output_invalid:'报告未完成'}
const changeLabels:Record<string,string>={new:'新发现',updated:'已有更新',known:'已知无变化',in_library:'已在库'}
const active=computed(()=>runs.value.find(r=>['dispatching','queued','running'].includes(r.status)))
const visibleItems=computed(()=>items.value.filter(i=>!pendingOnly.value||(i.decision==='pending'&&!i.in_library)))
const mainPane=ref<HTMLElement|null>(null)
let restoreScroll=0,hasRestored=false
let timer:ReturnType<typeof setInterval>|null=null,epoch=0
function defaults():FrontierConfig{return {goal:'',domains:[],keywords:[],authors:[],teams:[],exclude:[],sources:['arxiv','github'],collection_ids:[],interval_hours:24,lookback_days:30,max_results:5,daily_run_limit:4}}
function entity(i:FrontierItem){return i.entity_id??Number(i.id)}
function itemKey(i:FrontierItem){return `${i.topic_id??selected.value}:${entity(i)}`}
function date(s:string){return new Date(s.replace(' ','T')+'Z').toLocaleString('zh-CN',{hour12:false})}
function day(s:string){return new Date(s.replace(' ','T')+'Z').toLocaleDateString('zh-CN')}
function persist(){restoreScroll=mainPane.value?.scrollTop??restoreScroll;localStorage.setItem('frontier-view-v1',JSON.stringify({selected:selected.value,tab:tab.value,expanded:[...expanded.value],scroll:restoreScroll}))}
watch([selected,tab],persist)
async function refresh(background=false){const e=++epoch;if(!background)loading.value=true;try{const [t,c]=await Promise.all([frontierApi.topics(),papersApi.collections()]);if(e!==epoch)return;topics.value=t.topics;collections.value=c.collections;const [r,i,h]=await Promise.all([frontierApi.reports(selected.value??undefined),frontierApi.items(selected.value??undefined),selected.value?frontierApi.runs(selected.value):Promise.resolve({runs:[]})]);if(e!==epoch)return;if(background&&r.reports[0]?.id!==reports.value[0]?.id)newReports.value=true;else if(!background){reports.value=r.reports;cursor.value=r.next_cursor;if(!expanded.value.size&&r.reports[0])expanded.value.add(r.reports[0].id)}if(background){const fresh=new Map(r.reports.map(x=>[x.id,x]));reports.value=reports.value.map(x=>fresh.has(x.id)?{...x,items:fresh.get(x.id)!.items}:x)}if(background&&items.value.length){const incoming=new Map(i.items.map(x=>[itemKey(x),x]));const oldKeys=new Set(items.value.map(itemKey));items.value=[...i.items.filter(x=>!oldKeys.has(itemKey(x))),...items.value.map(x=>incoming.get(itemKey(x))??x)]}else{items.value=i.items;itemCursor.value=i.next_cursor??null}runs.value=h.runs;error.value='';if(!hasRestored){hasRestored=true;await nextTick();if(mainPane.value)mainPane.value.scrollTop=restoreScroll}}catch(e){if(!background)error.value=e instanceof Error?e.message:'载入失败'}finally{if(e===epoch)loading.value=false}}
function choose(id:number|null){selected.value=id;marked.value.clear();reports.value=[];void refresh()}
async function action(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
function startEdit(t?:FrontierTopic){editId.value=t?.id??null;editRevision.value=t?.revision??1;title.value=t?.title??'';config.value=JSON.parse(JSON.stringify(t?.config??defaults()));for(const k of Object.keys(fields.value) as Array<keyof typeof fields.value>)fields.value[k]=config.value[k].join(', ');formOpen.value=true}
async function save(){await action(async()=>{for(const k of Object.keys(fields.value) as Array<keyof typeof fields.value>)config.value[k]=fields.value[k].split(/[,，\n]/).map(x=>x.trim()).filter(Boolean);if(!config.value.goal.trim()&&!['domains','keywords','authors','teams'].some(k=>(config.value[k as 'domains']??[]).length))throw new Error('请至少填写研究目标、领域、关键词、作者或团队之一');const b={title:title.value,config:config.value};const t=editId.value?await frontierApi.update(editId.value,{...b,revision:editRevision.value}):await frontierApi.create(b);selected.value=t.id;formOpen.value=false;await refresh();notice.value='配置已保存。新建主题默认暂停。'})}
async function run(){if(!topic.value)return;const id=topic.value.id;await action(async()=>{await frontierApi.trigger(id,uid32());tab.value='runs';await refresh();notice.value='已交给现有智能体，查看历史不会重复执行。'})}
async function toggle(){if(!topic.value?.schedule)return;const s=topic.value.schedule;await action(async()=>{await schedulesApi.enable(s.id,!s.enabled);await refresh()})}
async function expand(r:FrontierRun){if(expanded.value.has(r.id))expanded.value.delete(r.id);else{expanded.value.add(r.id);await frontierApi.read(r.id);r.is_read=true}expanded.value=new Set(expanded.value);persist()}
async function older(){if(!cursor.value)return;await action(async()=>{const r=await frontierApi.reports(selected.value??undefined,cursor.value??undefined);const ids=new Set(reports.value.map(x=>x.id));reports.value.push(...r.reports.filter(x=>!ids.has(x.id)));cursor.value=r.next_cursor})}
async function olderItems(){if(!itemCursor.value)return;await action(async()=>{const data=await frontierApi.items(selected.value??undefined,itemCursor.value!);const keys=new Set(items.value.map(itemKey));items.value.push(...data.items.filter(i=>!keys.has(itemKey(i))));itemCursor.value=data.next_cursor??null})}
function renderReport(text:string){return renderMarkdown(text)}
function exportReport(r:FrontierRun){const url=URL.createObjectURL(new Blob([r.report_md],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`frontier-${r.id}.md`;a.click();URL.revokeObjectURL(url)}
function approve(i:FrontierItem){decisionItem.value=i;decisionCategories.value=[...(topics.value.find(t=>t.id===(i.topic_id??selected.value))?.config.collection_ids??[])];confirmDistinct.value=false}
async function decide(i:FrontierItem,which:string){await action(async()=>{await frontierApi.decision(i.topic_id??selected.value!,entity(i),{action:which,revision:i.revision,request_key:uid32(),collection_ids:which==='approve'?decisionCategories.value:[],confirm_distinct:confirmDistinct.value});decisionItem.value=null;await refresh();emit('library-updated');notice.value=which==='approve'?'已入库。缺全文时可在论文库补充 PDF。':'处理状态已保存'})}
async function batch(){await action(async()=>{const chosen=items.value.filter(i=>marked.value.has(itemKey(i))&&!i.in_library&&i.decision==='pending');const r=await frontierApi.batch(chosen.map(i=>({topic_id:i.topic_id,entity_id:entity(i),decision:{action:'approve',revision:i.revision,request_key:uid32(),collection_ids:topics.value.find(t=>t.id===i.topic_id)?.config.collection_ids??[]}})));notice.value=`成功 ${r.results.filter(x=>x.saved).length} 项，失败 ${r.results.filter(x=>!x.saved).length} 项`+(r.results.some(x=>x.error)?'；'+r.results.filter(x=>x.error).map(x=>x.error).join('；'):'');marked.value.clear();await refresh();emit('library-updated')})}
async function addCategory(target:'config'|'decision'){await action(async()=>{const c=await papersApi.createCollection(newCategory.value);collections.value.push(c);(target==='config'?config.value.collection_ids:decisionCategories.value).push(c.id);newCategory.value='';emit('library-updated')})}
onMounted(()=>{try{const s=JSON.parse(localStorage.getItem('frontier-view-v1')||'{}');selected.value=s.selected??null;tab.value=['reports','discoveries','runs'].includes(s.tab)?s.tab:'reports';expanded.value=new Set(s.expanded??[]);restoreScroll=s.scroll??0}catch{}void refresh();timer=setInterval(()=>void refresh(true),8000)})
onUnmounted(()=>{persist();epoch++;if(timer)clearInterval(timer)})
</script>
<template>
<div class="frontier-workspace">
 <aside class="frontier-sidebar"><button class="primary" @click="startEdit()">＋ 新建追踪主题</button><button :class="{selected:selected===null}" @click="choose(null)">全部主题与报告</button><h2>追踪主题</h2><select v-model="domainFilter" aria-label="按领域筛选追踪主题"><option value="">全部领域</option><option v-for="d in domains" :key="d" :value="d">{{d}}</option></select><button v-for="t in navTopics" :key="t.id" :class="{selected:selected===t.id}" @click="choose(t.id)"><span>{{t.title}}</span><small>{{t.schedule?.enabled?'追踪中':'已暂停'}} · 待批准 {{t.pending_count}}</small></button><p class="muted">复用现有智能体与 Skills。新主题默认暂停，报告不自动入库。</p></aside>
 <section ref="mainPane" class="frontier-main" @scroll.passive="persist">
 <header class="frontier-heading"><div><p class="eyebrow">RESEARCH FRONTIER</p><h1>{{topic?.title??'前沿追踪'}}</h1><p class="muted">发现论文与开源项目，经全局去重后生成时间线报告。</p></div><div class="actions"><button @click="refresh()">刷新</button><template v-if="topic"><button :disabled="busy" @click="startEdit(topic)">配置</button><button :disabled="busy" @click="toggle">{{topic.schedule?.enabled?'暂停追踪':'启用追踪'}}</button><button class="primary" :disabled="busy||!!active" @click="run">执行一次</button></template></div></header>
 <p v-if="topic?.schedule" class="muted">{{topic.schedule.enabled?'已启用':'已暂停'}} · 每 {{topic.config.interval_hours}} 小时 · 下次 {{topic.schedule.enabled?date(topic.schedule.next_at):'启用后安排'}} · 每来源最多 {{topic.config.max_results}} 条 · 每日最多 {{topic.config.daily_run_limit}} 轮</p>
 <StateFeedback :loading="loading&&!reports.length" :error="error||null" @retry="refresh()"/><p v-if="notice" role="status">{{notice}}</p>
 <nav class="frontier-tabs"><button :class="{selected:tab==='reports'}" @click="tab='reports'">前沿报告</button><button :class="{selected:tab==='discoveries'}" @click="tab='discoveries'">发现与批准</button><button :class="{selected:tab==='runs'}" @click="tab='runs'">运行记录</button></nav>
 <template v-if="tab==='reports'">
  <button v-if="newReports" class="primary" @click="newReports=false;refresh()">有新报告，点击查看</button>
  <div class="report-timeline"><template v-for="(r,index) in reports" :key="r.id"><h2 v-if="index===0||day(r.finished_at??r.created_at)!==day(reports[index-1]!.finished_at??reports[index-1]!.created_at)" class="timeline-day">{{day(r.finished_at??r.created_at)}}</h2><article class="timeline-node"><div class="timeline-dot"></div><div class="report-card"><button class="report-toggle" :aria-expanded="expanded.has(r.id)" @click="expand(r)"><strong>{{r.topic_title}} <small v-if="!r.is_read">未读</small></strong><span>{{date(r.finished_at??r.created_at)}} · {{labels[r.status]??r.status}} {{expanded.has(r.id)?'▾':'▸'}}</span></button><p class="report-counts">新增 {{r.counts.new??0}} · 已有更新 {{r.counts.updated??0}} · 已知无变化 {{(r.counts.known??0)+(r.counts.in_library??0)}} · 版本 {{r.version}}</p><template v-if="expanded.has(r.id)"><div class="report-body markdown-content" v-html="renderReport(r.report_md)"></div><details><summary>来源覆盖与用量</summary><p v-for="(c,j) in r.coverage" :key="j">{{c.source}}：{{c.status==='complete'?'已检索':'失败'}} · 召回 {{c.retrieved}} / 命中 {{c.total}}{{c.truncated?' · 已截断，覆盖不完整':''}} {{c.error}}</p><p>费用估算：{{r.cost===null?'未提供':'$'+r.cost.toFixed(4)}} · 用量 {{JSON.stringify(r.usage)}}</p></details><div v-for="i in r.items.filter(x=>x.change_type==='new'||x.change_type==='updated')" :key="i.id" class="report-item"><small>{{changeLabels[i.change_type??'']}}</small><strong>{{i.metadata.title}}</strong><p>{{i.reason}}</p><small>证据 {{i.id}} · {{i.metadata.evidence_level==='abstract'?'摘要':'元数据'}} · {{i.metadata.published??i.metadata.activity_at??'日期未提供'}}</small><div class="actions"><a :href="i.metadata.url" target="_blank" rel="noopener noreferrer">原始来源 ↗</a><button v-if="i.paper_id" @click="emit('open-paper',i.paper_id)">打开库内论文</button><span v-else-if="i.project_id">项目已在库</span><span v-else-if="i.decision==='ignored'">已忽略</span><button v-else :disabled="busy" @click="approve({...i,topic_id:r.topic_id})">批准入库</button></div></div><details v-if="r.items.some(x=>x.change_type==='known'||x.change_type==='in_library')"><summary>已知无变化条目（不重复计为新发现）</summary><p v-for="i in r.items.filter(x=>x.change_type==='known'||x.change_type==='in_library')" :key="i.id">{{i.metadata.title}} · {{i.in_library?'已在库':'历史候选'}} <button v-if="i.paper_id" @click="emit('open-paper',i.paper_id)">打开</button></p></details><button @click="exportReport(r)">导出报告 MD</button><button @click="action(async()=>{const s=await frontierApi.discussion(r.id);emit('open-session',s.session_id)})">在关联会话继续讨论</button></template></div></article></template></div>
  <p v-if="!loading&&!reports.length" class="empty">暂无报告。新建主题并执行一次，报告完成后将出现在这里。</p><button v-if="cursor" :disabled="busy" @click="older">加载更早报告</button>
 </template>
 <template v-if="tab==='discoveries'"><div class="actions"><label><input v-model="pendingOnly" type="checkbox">只看待批准</label><button :disabled="!marked.size||busy" @click="batch">批准所选 {{marked.size}} 项</button></div><article v-for="i in visibleItems" :key="itemKey(i)" class="discovery-card"><label v-if="!i.in_library&&i.decision==='pending'"><input type="checkbox" :checked="marked.has(itemKey(i))" @change="marked.has(itemKey(i))?marked.delete(itemKey(i)):marked.add(itemKey(i))">选择</label><h3>{{i.metadata.title}}</h3><p>{{i.metadata.abstract??i.metadata.description}}</p><p class="muted">{{i.kind==='project'?'开源项目':'论文'}} · {{i.in_library?'已在库':i.decision==='ignored'?'已忽略':i.decision==='approved'?'已批准':'待批准'}} · {{i.metadata.authors?.join(' · ')??i.metadata.owner}}</p><p v-if="i.similar_paper_ids?.length" class="warning">题名与已有论文相同，需先核验身份：{{i.similar_paper_ids.join(', ')}}</p><div class="actions"><a :href="i.metadata.url" target="_blank" rel="noopener noreferrer">原始来源 ↗</a><button v-if="i.paper_id" @click="emit('open-paper',i.paper_id)">打开库内论文</button><button v-if="!i.in_library&&i.decision!=='ignored'" :disabled="busy" @click="approve(i)">批准入库</button><button v-if="!i.in_library&&i.decision!=='ignored'" :disabled="busy" @click="decide(i,'ignore')">忽略</button><button v-if="i.decision==='ignored'" :disabled="busy" @click="decide(i,'reopen')">恢复待处理</button></div></article><button v-if="itemCursor" :disabled="busy" @click="olderItems">加载更早发现</button><p v-if="!items.length" class="empty">暂无发现，执行追踪后将显示候选及去重状态。</p></template>
 <template v-if="tab==='runs'"><p v-if="!topic" class="empty">从左侧选择主题查看运行记录。</p><article v-for="r in runs" :key="r.id" class="discovery-card"><strong>{{labels[r.status]??r.status}}</strong> · {{date(r.created_at)}}<p v-if="r.error" class="warning">{{r.error}}</p><div class="actions"><button v-if="['queued','running','dispatching'].includes(r.status)" :disabled="busy" @click="action(async()=>{await frontierApi.cancel(r.id);await refresh()})">停止本轮</button><button @click="emit('open-session',r.conversation_id)">查看智能体会话</button></div></article></template>
 </section>
 <div v-if="formOpen" class="frontier-overlay" @click.self="!busy&&(formOpen=false)"><form class="frontier-dialog" @submit.prevent="save"><h2>{{editId?'编辑':'新建'}}追踪主题</h2><label>名称<input v-model="title" maxlength="160" required></label><label>研究目标<textarea v-model="config.goal" maxlength="1500" placeholder="你希望持续了解什么问题？"></textarea></label><label v-for="(label,k) in {domains:'领域（可选已有或新增）',keywords:'关键词',authors:'作者',teams:'团队 / 机构',exclude:'排除词'}" :key="k">{{label}}<input v-model="fields[k]" :list="'frontier-'+k" placeholder="可选，多项用逗号分隔"></label><datalist v-for="k in ['keywords','authors','teams','exclude'] as const" :id="'frontier-'+k" :key="k"><option v-for="v in [...new Set(topics.flatMap(t=>t.config[k]))]" :key="v" :value="v"/></datalist><datalist id="frontier-domains"><option v-for="c in collections" :key="c.id" :value="c.name"/></datalist><fieldset><legend>数据源</legend><label v-for="source in ['arxiv','crossref','github']" :key="source"><input v-model="config.sources" type="checkbox" :value="source">{{source}}</label></fieldset><div class="form-grid"><label>间隔（小时）<input v-model.number="config.interval_hours" type="number" min="1" max="8760" required></label><label>首次回看（天）<input v-model.number="config.lookback_days" type="number" min="1" max="365" required></label><label>每来源最多条数<input v-model.number="config.max_results" type="number" min="1" max="20" required></label><label>每日最多运行<input v-model.number="config.daily_run_limit" type="number" min="1" max="24" required></label></div><label>入库建议分类<select v-model="config.collection_ids" multiple><option v-for="c in collections" :key="c.id" :value="c.id">{{c.path ?? c.name}}</option></select></label><div class="actions"><input v-model="newCategory" placeholder="新增分类"><button type="button" :disabled="busy||!newCategory.trim()" @click="addCategory('config')">添加</button></div><p class="muted">现有智能体执行 Nature 发现流程适配 Skill。单轮预算上限 $0.20，网关估算不等于实际账单。默认不精读、不下载、不自动入库。</p><p v-if="error" class="warning">{{error}}</p><div class="actions"><button type="button" :disabled="busy" @click="formOpen=false">取消</button><button class="primary" :disabled="busy||!config.sources.length">{{busy?'保存中…':'保存配置'}}</button></div></form></div>
 <div v-if="decisionItem" class="frontier-overlay"><form class="frontier-dialog" @submit.prevent="decide(decisionItem!,'approve')"><h2>批准入库</h2><strong>{{decisionItem.metadata.title}}</strong><label>选择分类<select v-model="decisionCategories" multiple><option v-for="c in collections" :key="c.id" :value="c.id">{{c.path ?? c.name}}</option></select></label><div class="actions"><input v-model="newCategory" placeholder="新分类名称"><button type="button" :disabled="busy||!newCategory.trim()" @click="addCategory('decision')">添加分类</button></div><label v-if="decisionItem.similar_paper_ids?.length"><input v-model="confirmDistinct" type="checkbox">已核验，与同名论文是独立资料</label><p class="muted">保存书目或项目资料；缺 PDF 时稍后补充。重复资料关联原条目。</p><p v-if="error" class="warning">{{error}}</p><div class="actions"><button type="button" :disabled="busy" @click="decisionItem=null">取消</button><button class="primary" :disabled="busy">批准并保存</button></div></form></div>
</div>
</template>
<style scoped>
